@if($mode === 'duktek')<section id="monitoring" class="tab-panel"><div class="section-head"><h2>Monitoring 3 Satlak</h2><p>Duktek dapat melihat aktivitas laporan dari Penangkalan, Siber Sosial, dan Penindakan, termasuk tujuan laporan, isi aktivitas, status, serta lampiran yang tersedia.</p></div><div class="monitor-grid">@foreach($monitoringSatlak as $m)<div class="monitor-card"><div class="name">{{ $m['nama'] }}</div><div class="num">{{ $m['total'] }}</div><div class="sub">Laporan dalam sistem</div></div>@endforeach</div><div class="panel" style="margin-top:16px"><div class="tbl-wrap"><table class="dtbl"><thead><tr><th>Satlak</th><th>Perihal</th><th>Prioritas</th><th>Status</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody>@forelse($laporanSatlak as $l)<tr><td>{{ $l->satuan->nama ?? '-' }}</td><td>{{ $l->perihal }}</td><td>{{ $l->prioritas }}</td><td><span class="status-dot {{ str_contains(strtolower($l->status),'setuj') || str_contains(strtolower($l->status),'diterima') ? 'green' : (str_contains(strtolower($l->status),'tolak') ? 'bad' : 'amber') }}">{{ $l->status }}</span></td><td>{{ $l->created_at->translatedFormat('d M Y H:i') }}</td><td><button type="button" class="monitor-detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($l->satuan->nama ?? '-') }}" data-tujuan="{{ e($l->tujuanSatuan->nama ?? '-') }}" data-perihal="{{ e($l->perihal) }}" data-prioritas="{{ e($l->prioritas) }}" data-proyek="{{ e($l->proyek ?? '-') }}" data-tanggal="{{ e($l->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($l->deskripsi) }}" data-lampiran="{{ $l->lampiran_path ? e(asset('storage/'.$l->lampiran_path)) : '' }}" data-readonly="1">Lihat Detail</button></td></tr>@empty<tr><td colspan="6" style="text-align:center;color:var(--text-muted);padding:28px">Belum ada laporan dari 3 Satlak.</td></tr>@endforelse</tbody></table></div></div></section>@endif
